      id: 'payoff-gremlin-caged', kind: 'prose',
      heading: { en: 'The Gremlin, caged', ru: 'Гремлин в клетке', tt: 'Читлектәге Гремлин' },
      img: 'L6/L6-15-gremlin-caged.png', imgPos: 'hero',
